const predictions = $input.first().json.predictions || [];
const critical = predictions.filter(p => p.riskLevel === 'critical');
const high = predictions.filter(p => p.riskLevel === 'high');
return critical.concat(high).map(p => ({ json: p }));

const items = $input.all();
const grouped = {};
for (const item of items) {
  const rig = item.json.rigName;
  if (!grouped[rig]) grouped[rig] = [];
  grouped[rig].push(item.json);
}
let html = '<h2>⚠️ Predictive Maintenance Alert</h2>';
for (const [rig, components] of Object.entries(grouped)) {
  html += `<h3>${rig}</h3><ul>`;
  for (const c of components) {
    const emoji = c.riskLevel === 'critical' ? '🔴' : '🟠';
    html += `<li>${emoji} <b>${c.componentName}</b> — ${Math.round(c.failureProbability30d * 100)}% failure probability in 30 days<br><small>Risk factors: ${c.riskFactors?.join(', ') || 'N/A'}</small></li>`;
  }
  html += '</ul>';
}
return [{ json: { emailBody: html, count: items.length } }];
